insert into public.ce_course1_resources(id,data) values
('contrast_dyes_pdf','{"base64": "", "sha256": "0019de9f258c92bf2fe7fd3d07f9e4bf61334c072c9dd727ff8b83b8c371a88b", "filename": "CE_HALO_Contrast_Dyes_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('contrast_dyes_questions','[{"module_id": "course_1_module_6", "question_id": "course_1_module_6_q01", "question_number": 1, "stem": "Which of the following BEST distinguishes iodinated contrast media from gadolinium-based contrast agents (GBCAs) in perioperative practice?", "choice_a": "Iodinated agents are used for fluoroscopy/angiography; GBCAs are primarily used with MRI and carry NSF risk in severe kidney dysfunction", "choice_b": "GBCAs are used for CT; iodinated contrast is exclusive to ultrasound", "choice_c": "GBCAs and iodinated contrast are interchangeable in the OR", "choice_d": "Both are radiographic contrast; both share identical renal risk profiles", "correct_choice": "a", "rationale": "Iodinated contrast is the standard for fluoroscopy and angiography, while GBCAs are used with MRI. GBCAs carry unique NSF risk in severe renal dysfunction, especially with older Group I agents (Welker et al., 2025; ACR Committee on Drugs and Contrast Media, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q02", "question_number": 2, "stem": "Indocyanine green (ICG) is BEST described as:", "choice_a": "A local anesthetic dye for spinal use", "choice_b": "An optical/fluorescent imaging agent used with near-infrared systems for perfusion and biliary visualization", "choice_c": "A radiographic contrast agent used for angiography", "choice_d": "A gadolinium-based MR contrast agent", "correct_choice": "b", "rationale": "ICG is an optical imaging agent used with near-infrared fluorescence systems for perfusion assessment and biliary visualization (De Simone et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q03", "question_number": 3, "stem": "A patient with a reported ''shellfish allergy'' is scheduled for angiography. Which statement is MOST accurate?", "choice_a": "The procedure must be canceled", "choice_b": "The patient requires prophylactic dialysis before contrast", "choice_c": "Shellfish allergy does not, by itself, establish a true contrast allergy; prior reaction to the same class of contrast is the most useful history", "choice_d": "Shellfish allergy is a definite contraindication to iodinated contrast", "correct_choice": "c", "rationale": "AAAAI and current allergy literature confirm that shellfish or generic ''iodine'' allergy does not establish contrast allergy. The clinically useful history is prior reaction to the same class of contrast agent (AAAAI, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q04", "question_number": 4, "stem": "Which category BEST describes an ACR-defined SEVERE acute contrast reaction?", "choice_a": "Diffuse urticaria with mild bronchospasm", "choice_b": "Skin discoloration only", "choice_c": "Limited urticaria and mild nausea", "choice_d": "Laryngeal edema with stridor/hypoxia, severe bronchospasm with hypoxia, or anaphylactic shock", "correct_choice": "d", "rationale": "Severity depends on physiologic compromise; throat symptoms without dyspnea are not equivalent to laryngeal edema with stridor or hypoxia.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [1], "source_urls": ["https://geiselmed.dartmouth.edu/radiology/wp-content/uploads/sites/47/2024/08/ACR-contrast-2024.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q05", "question_number": 5, "stem": "Preferred terminology for kidney injury temporally associated with contrast administration is:", "choice_a": "Contrast-associated acute kidney injury (CA-AKI) to reflect temporal association without assuming direct causation", "choice_b": "Post-renal failure", "choice_c": "Acute tubular necrosis", "choice_d": "Contrast-induced acute kidney injury (CI-AKI) in all cases", "correct_choice": "a", "rationale": "Contemporary sources prefer CA-AKI to acknowledge that perioperative AKI often has multiple competing causes — hypotension, sepsis, nephrotoxins — beyond the contrast itself (ACR Committee on Drugs and Contrast Media, 2025; Frontiers in Nephrology, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q06", "question_number": 6, "stem": "Which patient scenario carries the HIGHEST risk of CA-AKI after iodinated contrast?", "choice_a": "eGFR 90, elective outpatient CT", "choice_b": "eGFR 22, recent AKI, and intraoperative hypotension", "choice_c": "eGFR 65, euvolemic, stable hemodynamics", "choice_d": "eGFR 55, stable, oral hydration", "correct_choice": "b", "rationale": "Advanced CKD (eGFR <30), recent AKI, and major hemodynamic instability represent the highest-risk stratum for CA-AKI (ESUR Contrast Media Safety Committee, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q07", "question_number": 7, "stem": "Under ACR guidance, a patient taking metformin has no AKI and stable eGFR 55 before IV contrast CT. What is appropriate?", "choice_a": "Substitute insulin for the day", "choice_b": "Withhold metformin for 48 hours before and after contrast", "choice_c": "Continue metformin; no routine hold is required at this eGFR with IV contrast", "choice_d": "Cancel the study", "correct_choice": "c", "rationale": "The 2024 ACR framework and the 2025 Xu et al. systematic review support continuing metformin in patients with eGFR ≥30 and stable renal function receiving IV or below-the-diaphragm intra-arterial contrast (ACR Committee on Drugs and Contrast Media, 2025; Xu et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://geiselmed.dartmouth.edu/radiology/wp-content/uploads/sites/47/2024/08/ACR-contrast-2024.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q08", "question_number": 8, "stem": "Under the ACR framework, how should metformin be managed with iodinated contrast in a patient with eGFR 24?", "choice_a": "Restart automatically at 48 hours even if eGFR remains below 30", "choice_b": "Hold only until the contrast injection ends", "choice_c": "Continue without reassessment", "choice_d": "Withhold at/before contrast and for 48 hours; reassess renal function and eligibility", "correct_choice": "d", "rationale": "AKI or eGFR below 30 requires reassessment; a 48-hour interval does not itself make restarting safe.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://geiselmed.dartmouth.edu/radiology/wp-content/uploads/sites/47/2024/08/ACR-contrast-2024.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q09", "question_number": 9, "stem": "The primary unique concern with gadolinium-based contrast agents in patients with severe kidney dysfunction is:", "choice_a": "Nephrogenic systemic fibrosis (NSF), particularly with older Group I agents", "choice_b": "Contrast-induced hepatic injury", "choice_c": "Immediate anaphylaxis risk higher than iodinated contrast", "choice_d": "Cardiac arrhythmias", "correct_choice": "a", "rationale": "The dominant CRNA concern with GBCAs in advanced CKD is NSF, highest with older, less-stable Group I agents. Group II macrocyclic GBCAs carry substantially lower risk (Welker et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q10", "question_number": 10, "stem": "According to the 2025 ASNR position statement, GBCA use in stable CKD patients who require MRI:", "choice_a": "Is absolutely contraindicated regardless of agent", "choice_b": "Use a clinically appropriate Group II agent; the group includes macrocyclic and some linear agents", "choice_c": "Is safe only in dialysis-dependent patients", "choice_d": "Requires mandatory hemodialysis after every dose", "correct_choice": "b", "rationale": "NSF-risk groups are not synonymous with chemical structure. Do not start prophylactic dialysis solely for Group II contrast.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://geiselmed.dartmouth.edu/radiology/wp-content/uploads/sites/47/2024/08/ACR-contrast-2024.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q11", "question_number": 11, "stem": "Methylene blue can precipitate serotonin toxicity primarily by:", "choice_a": "Direct 5-HT release from platelets", "choice_b": "Blocking dopamine reuptake", "choice_c": "Inhibiting monoamine oxidase (MAO)", "choice_d": "Antagonizing serotonin receptors", "correct_choice": "c", "rationale": "Methylene blue is a potent MAO inhibitor and can precipitate serotonin toxicity when combined with serotonergic agents (APSF, 2024; Francescangeli et al., 2016).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q12", "question_number": 12, "stem": "Which medication combination with methylene blue carries the HIGHEST risk of serotonin toxicity?", "choice_a": "Beta-blocker and calcium channel blocker", "choice_b": "Aspirin and clopidogrel", "choice_c": "Acetaminophen and ondansetron", "choice_d": "SSRI, SNRI, MAOI, linezolid, or certain TCAs", "correct_choice": "d", "rationale": "Review serotonergic medications and opioids; the PROVAYBLUE boxed warning advises avoiding concomitant use because serious serotonin syndrome can occur.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [2], "source_urls": ["https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/204630Orig1s023correctedlbl.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q13", "question_number": 13, "stem": "A patient on chronic SSRI receives intraoperative methylene blue and develops hypertension, agitation, clonus, and hyperthermia in PACU. The MOST likely diagnosis is:", "choice_a": "Serotonin toxicity related to methylene blue and SSRI co-exposure", "choice_b": "Postoperative delirium unrelated to medications", "choice_c": "Malignant hyperthermia", "choice_d": "Neuroleptic malignant syndrome", "correct_choice": "a", "rationale": "The clinical triad of autonomic instability, neuromuscular changes (clonus, rigidity), and altered mental status after methylene blue in an SSRI-treated patient strongly suggests serotonin toxicity (Francescangeli et al., 2016).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q14", "question_number": 14, "stem": "What is the appropriate response when PROVAYBLUE is planned for a patient with known G6PD deficiency?", "choice_a": "Use it to correct G6PD deficiency", "choice_b": "Identify the contraindication, notify the team, and select an alternative", "choice_c": "Give half the usual dose without discussion", "choice_d": "Proceed because dye doses cannot cause hemolysis", "correct_choice": "b", "rationale": "PROVAYBLUE is contraindicated because severe hemolysis can occur and treatment may be ineffective.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [2], "source_urls": ["https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/204630Orig1s023correctedlbl.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q15", "question_number": 15, "stem": "Indocyanine green anaphylaxis during intraoperative use is BEST described as:", "choice_a": "Only reported in ophthalmic procedures", "choice_b": "The most common cause of intraoperative reactions", "choice_c": "Rare but documented; ICG should be included in the intraoperative hypersensitivity differential", "choice_d": "Impossible — ICG has no allergenic potential", "correct_choice": "c", "rationale": "ICG anaphylaxis is rare but well-documented in abdominal, colorectal, and other perioperative settings. Rare does not mean irrelevant — include ICG in the intraoperative reaction differential (Anaphylaxis Induced by ICG PMC report, 2024; De Simone et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q16", "question_number": 16, "stem": "A patient receiving ICG during robotic colorectal surgery develops sudden erythema, increasing airway pressures, and hypotension. The MOST appropriate response is:", "choice_a": "Reverse anesthesia immediately", "choice_b": "Administer additional ICG to confirm the reaction", "choice_c": "Continue surgery — ICG cannot cause anaphylaxis", "choice_d": "Stop exposure, call for help, support airway/circulation, and give epinephrine using the perioperative anaphylaxis protocol", "correct_choice": "d", "rationale": "This pattern requires urgent anaphylaxis treatment. Epinephrine route and dosing depend on the setting; titrated IV dosing is for trained clinicians with appropriate monitoring, not interchangeable with IM dosing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q17", "question_number": 17, "stem": "Fluorescein administration is MOST likely to cause:", "choice_a": "Nausea, vomiting, and skin/urine discoloration; occasional severe hypersensitivity", "choice_b": "Immediate anaphylaxis in every patient", "choice_c": "Renal failure in all patients", "choice_d": "Cardiac arrest as the most common reaction", "correct_choice": "a", "rationale": "The most common fluorescein reactions are nausea, vomiting, and skin/urine discoloration. Severe hypersensitivity is uncommon but documented (Ge & O''Shea, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q18", "question_number": 18, "stem": "Which of the following is the MOST important historical risk factor for recurrent iodinated contrast reaction?", "choice_a": "Shellfish allergy", "choice_b": "Prior reaction to the same class of iodinated contrast agent", "choice_c": "Asthma alone", "choice_d": "Multiple unrelated drug allergies", "correct_choice": "b", "rationale": "A prior reaction to the same class of contrast agent is the single most important predictor of recurrence — more predictive than asthma, unrelated allergies, or shellfish history (ACR Committee on Drugs and Contrast Media, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q19", "question_number": 19, "stem": "Contemporary guidance on premedication for prior contrast reactions:", "choice_a": "Eliminates the need for reaction preparedness", "choice_b": "Recommends universal premedication for all allergic patients", "choice_c": "Is more selective — targeted premedication for high-risk histories, with understanding that it does not eliminate reaction risk", "choice_d": "Requires 48 hours of steroid loading in every case", "correct_choice": "c", "rationale": "Contemporary guidance is more selective, and premedication does not eliminate reaction risk. Readiness to treat an acute event remains essential regardless of premedication (ACR Committee on Drugs and Contrast Media, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q20", "question_number": 20, "stem": "A 72-year-old undergoing endovascular aneurysm repair develops sudden hypotension, tachycardia, and bronchospasm immediately after iodinated contrast injection. The MOST appropriate initial action is:", "choice_a": "Deepen anesthesia and continue", "choice_b": "Assume hemorrhage and give massive transfusion first", "choice_c": "Continue contrast to complete imaging", "choice_d": "Stop exposure, call for help, support airway/circulation, and treat with epinephrine per the perioperative anaphylaxis protocol", "correct_choice": "d", "rationale": "Treat anaphylaxis promptly while assessing other causes. Route, dose, and monitoring must follow the perioperative protocol; IM and IV doses are not interchangeable.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q21", "question_number": 21, "stem": "Extravasation of iodinated contrast at the injection site should be managed with:", "choice_a": "Stopping injection, elevating the extremity, assessing for compartment syndrome or severe tissue injury, and documenting", "choice_b": "Continued injection to flush the extravasated volume", "choice_c": "No specific action — extravasation is always benign", "choice_d": "Immediate surgical debridement in every case", "correct_choice": "a", "rationale": "Extravasation management includes stopping injection, elevation, assessment for compartment syndrome or severe injury, and clear documentation. Most events are self-limited but require attention (ACR Committee on Drugs and Contrast Media, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q22", "question_number": 22, "stem": "For a patient scheduled for MRI with GBCA who has stable eGFR 40 mL/min/1.73m², the BEST approach according to the 2025 ASNR statement is:", "choice_a": "Substitute iodinated contrast for MRI", "choice_b": "Use an appropriate Group II GBCA when indicated; routine prophylactic dialysis is not required", "choice_c": "Cancel the MRI entirely", "choice_d": "Require pre-procedure dialysis for every patient", "correct_choice": "b", "rationale": "Group II agents have very low NSF risk and include macrocyclic and some linear agents. Individualize selection with radiology.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://geiselmed.dartmouth.edu/radiology/wp-content/uploads/sites/47/2024/08/ACR-contrast-2024.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q23", "question_number": 23, "stem": "Which of the following BEST captures the CRNA preoperative approach when contrast or dye use is anticipated?", "choice_a": "Give universal steroid premedication regardless of history", "choice_b": "Delay all cases involving contrast", "choice_c": "Verify agent, indication, route/dose, and screen for prior reaction, advanced kidney disease, and high-risk medications (serotonergic co-therapy if methylene blue possible)", "choice_d": "No pre-op planning is required — contrast is a radiology-side issue", "correct_choice": "c", "rationale": "Structured pre-case verification — agent, indication, route, and focused history — is the CRNA''s core preparation for any perioperative contrast or dye use.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q24", "question_number": 24, "stem": "Which observation plan is appropriate during contrast or ICG administration?", "choice_a": "Observe only if premedication was omitted", "choice_b": "Wait for skin findings before assessing circulation", "choice_c": "Stop monitoring after 5 minutes", "choice_d": "Maintain immediate and continued vigilance; reactions are not limited to 5–10 minutes", "correct_choice": "d", "rationale": "Monitor the patient throughout the clinically appropriate period and respond promptly to airway or cardiovascular changes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [1], "source_urls": ["https://geiselmed.dartmouth.edu/radiology/wp-content/uploads/sites/47/2024/08/ACR-contrast-2024.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_6", "question_id": "course_1_module_6_q25", "question_number": 25, "stem": "Which single principle BEST summarizes the CRNA''s role with perioperative contrast and operative dyes?", "choice_a": "Treat every intravascular contrast or dye exposure as part of the anesthetic environment — anticipating reactions, individualizing renal-risk assessment, and screening for high-risk drug interactions", "choice_b": "Treat contrast as a radiology-side detail unrelated to anesthesia", "choice_c": "Focus only on hemodynamics; ignore renal and drug-interaction considerations", "choice_d": "Avoid all contrast use whenever possible", "correct_choice": "a", "rationale": "Every intravascular contrast or dye is part of the anesthetic environment. The CRNA anticipates reactions, individualizes renal risk, screens for drug interactions (especially methylene blue with serotonergic agents), and prepares for immediate management of hypersensitivity (ACR Committee on Drugs and Contrast Media, 2025; APSF, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.aaaai.org/tools-for-the-public/conditions-library/allergies/radiocontrast", "https://www.acr.org/Clinical-Resources/Clinical-Tools-and-Reference/Contrast-Manual", "https://www.apsf.org/article/methylene-blue-and-the-risk-of-serotonin-toxicity/", "https://doi.org/10.1186/s13017-025-00583-w", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/011525Orig1s039lbl.pdf", "https://www.esur.org/esur-guidelines-2025/", "https://doi.org/10.12659/AJCR.897298", "https://doi.org/10.3389/fneph.2025.1582775", "https://doi.org/10.3390/molecules29245964", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12017462/", "https://doi.org/10.3174/ajnr.A8578", "https://doi.org/10.3389/fmed.2025.1547725", "https://pmc.ncbi.nlm.nih.gov/articles/PMC12568759/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC11587973/"], "source_provenance": "provider_submitted_content_and_reference_list"}]'::jsonb)
